import * as fs from "fs";
import * as path from "path";
import { validateCodetourTour } from "./codetour-schema";
import { createContext } from "./context";
import {
  changedFiles,
  committedDiffIsEmpty,
  currentBranchName,
  currentHeadSha,
  isGitRepository,
  mergeBase,
  normalizeSlashes,
  readCommitAnchors,
  resolveCommit,
  uncommittedChanges,
  workspacePrefix,
} from "./git";
import { recordCreation } from "./journal";
import { OutputPathError, writeTourAtomic } from "./persistence";
import { stageCommitAnchors, validateTourProposal } from "./proposal-validation";
import {
  CreationFailure,
  CreationResult,
  CreateTourOptions,
  CreatedTour,
  TourFile,
  TourKind,
  TourStep,
  Warning,
  WorkspaceContext,
} from "./types";
import { MAX_RECOMMENDED_STEPS, orientationStepWarnings } from "./validation";

// Tour creation, free of any transport: both entry points take the
// workspace to create in and the proposal exactly as it arrived, validate it,
// apply the Git, image, Mermaid and workspace-confinement rules, write the
// Tour file atomically, and report the outcome as a value. Nothing here writes
// to a stream or reads a command line, so the command-line surface stays a thin
// adapter over these rules instead of reimplementing them.
//
// Validation always precedes the write: a rejected proposal writes no file and
// leaves any existing Tour untouched.

const CODETOUR_SCHEMA_URI = "https://aka.ms/codetour-schema";

// Fixed destinations reserved for generated Tours. They are replaced only
// after complete validation and ignored while detecting a dirty workspace (see
// git.ts).
const PROJECT_TOUR_PATH = ".tours/project.tour";
const CHANGES_TOUR_PATH = ".tours/changes.tour";

// A custom `fileName` is always confined to the `.tours` directory next to the
// reserved destinations; without one the reserved default applies.
function tourTargetPath(defaultPath: string, fileName?: string): string {
  return fileName === undefined ? defaultPath : `.tours/${fileName}`;
}

// The name of the entry point a rejection addresses: the caller's own surface
// name, or the command of that kind when the caller named none.
function surfaceName(kind: TourKind, options: CreateTourOptions): string {
  return options.surface ?? `create-${kind}-tour`;
}

function failure(code: string, message: string, issues?: CreationFailure["issues"]): CreationFailure {
  return {
    ok: false,
    code,
    message,
    ...(issues && issues.length > 0 ? { issues } : {}),
  };
}

// A written Tour as the kind-specific rules report it; the caller adds the
// kind and the workspace, then records the creation.
type WrittenTour = { ok: true } & Omit<CreatedTour, "kind" | "workspaceRoot">;
type WriteOutcome = WrittenTour | CreationFailure;

// Create a Project Tour: no Git access is required, the tour works in any
// workspace, and it is never attached to a `ref` so it remains viewable as the
// project evolves.

import { randomBytes } from "crypto";
import { promises as fs } from "fs";
import * as path from "path";
import { TourKind } from "./types";

// Creation journal: one record per created Tour, under
// `<workspace>/.tours/.log/creations/`. The hook surfaces of the agents read
// it to report the Tours a response actually created; the record therefore
// carries the creation time and whatever session identity the creating
// process could observe, and nothing else.
//
// It is observability only. A record is an independent file, written
// atomically after the Tour exists, so concurrent creations never contend for
// one document; a journal that cannot be written never fails the creation and
// is never reported as one.

/** Directory of the creation records, relative to the workspace root. */
export const CREATIONS_DIRECTORY = path.join(".tours", ".log", "creations");

export const CREATION_RECORD_VERSION = 1;

export interface CreationRecord {
  version: number;
  /** Canonical workspace root the creation was requested for. */
  workspace: string;
  /** Absolute path of the written Tour file. */
  tourPath: string;
  tourTitle: string;
  kind: TourKind;
  /** ISO timestamp of the successful write. */
  at: string;
  sessionId: string | null;
  responseId: string | null;
  host: string | null;
}

export interface CreationIdentity {
  sessionId: string | null;
  responseId: string | null;
  host: string | null;
}

function nonEmpty(value: string | undefined): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed === "" ? null : trimmed;
}

// The identity is read from the environment of the creating process only: a
// value CodeTour cannot observe stays null instead of being guessed. The
// explicit variables name the session, the response and the host; a host that
// exports its own session variable is used when it identifies the host, which
// is why its presence also states the host name. Both host variables were
// verified on the installed CLIs: Pi exports PI_SESSION_ID to the bash tool,
// and the Copilot CLI exports COPILOT_AGENT_SESSION_ID, whose value equals the
// `sessionId` its agentStop hook receives.
export function creationIdentity(
  env: Record<string, string | undefined> = process.env
): CreationIdentity {
  const explicitSession = nonEmpty(env.CODETOUR_SESSION_ID);
  const piSession = nonEmpty(env.PI_SESSION_ID);
  const copilotSession = nonEmpty(env.COPILOT_AGENT_SESSION_ID);
  const [sessionId, observedHost]: [string | null, string | null] =
    explicitSession !== null ? [explicitSession, null]
      : piSession !== null ? [piSession, "pi"]
        : copilotSession !== null ? [copilotSession, "copilot"]
          : [null, null];
  return {
    sessionId,
    responseId: nonEmpty(env.CODETOUR_RESPONSE_ID),
    host: nonEmpty(env.CODETOUR_HOST) ?? observedHost,
  };
}

export interface CreationRecordInput {
  workspaceRoot: string;
  tourPath: string;
  tourTitle: string;
  kind: TourKind;
}

// Write one creation record. Returns the written file, or undefined when the
// journal is unavailable; the caller treats that as a diagnostic, never as a
// failure of the creation itself.
export async function recordCreation(
  input: CreationRecordInput,
  identity: CreationIdentity = creationIdentity()
): Promise<string | undefined> {
  const createdAt = new Date();
  const record: CreationRecord = {
    version: CREATION_RECORD_VERSION,
    workspace: input.workspaceRoot,
    tourPath: input.tourPath,
    tourTitle: input.tourTitle,
    kind: input.kind,
    at: createdAt.toISOString(),
    sessionId: identity.sessionId,
    responseId: identity.responseId,
    host: identity.host,
  };
  const directory = path.join(input.workspaceRoot, CREATIONS_DIRECTORY);
  // `<createdAtMs>-<pid>-<random>`: sortable by time, unique under concurrent
  // creations from the same process.
  const fileName = `${createdAt.getTime()}-${process.pid}-${randomBytes(4).toString("hex")}.json`;
  const target = path.join(directory, fileName);
  const temporary = path.join(directory, `.${fileName}.tmp`);
  try {
    await fs.mkdir(directory, { recursive: true });
    await fs.writeFile(temporary, `${JSON.stringify(record, null, 2)}\n`, "utf8");
    await fs.rename(temporary, target);
    return target;
  } catch {
    await fs.rm(temporary, { force: true }).catch(() => undefined);
    return undefined;
  }
}

src/cli/copilot-plugin.generated.ts:10:  "README.md": "# CodeTour Copilot plugin

This directory is the versioned **Agent Plugins 1.0** source of the CodeTour
integration for GitHub Copilot CLI. It is embedded in the standalone CodeTour
CLI and installed by:

```sh
codetour --install copilot
```

`copilot plugin install packages/copilot-plugin` installs the same directory
directly (the installed CLI supports local direct installs, with a deprecation
warning). `copilot plugin uninstall codetour` removes it.

## Contents

| Path | Role |
| --- | --- |
| `plugin.json` | Agent Plugins 1.0 manifest (`$schema`, name, version, metadata). |
| `skills/codetour-generate/SKILL.md` | The generation entry point: the CLI creation commands, the proposal shape and the failure handling. |
| `com.github.copilot/hooks/hooks.json` | Copilot `agentStop` hook declaration. |
| `com.github.copilot/hooks/agent-stop.mjs` | End-of-response summary: the created Tours and one token reading. It never blocks. |
| `com.github.copilot/lib/run-log.mjs` | The creation-journal and session-transcript readers the hook uses. |
| `skills/codetour-generate/references/` | The path modules the skill reads before exploring (`project-tour.md`, `changes-tour-neutral.md`, `changes-tour-critical.md`), the Mermaid and anchor guidance, and the critical-review pack only the critical module carries: the CodeTour adaptation, the verbatim upstream skill and its MIT license. |

The plugin declares no MCP server: generation is the CLI's work, and the hook
only reads what the CLI wrote (ADR 0057).

## Generation

`/codetour-generate`, or a plain request to explain the codebase or review the
branch, follows
[`skills/codetour-generate/SKILL.md`](skills/codetour-generate/SKILL.md): it
resolves the Tour type, the review mode (Changes Tours only) and the orientation
phrase, explores the workspace, then hands a JSON proposal to the installed CLI
from the workspace root:

```sh
codetour create-project-tour --workspace "<absolute workspace root>" < proposal.json
codetour create-changes-tour --workspace "<absolute workspace root>" < proposal.json
```

The CLI validates the proposal, writes the Tour atomically and answers with one
JSON document on standard output: `ok: true` with the absolute `tourPath`, or
`ok: false` with `code`, `message` and the `issues` to correct. Nothing needs to
be installed beside the CLI and no repository checkout is involved.

## The agentStop summary

The hook is purely informative. It reads two files it does not own and writes
one marker:

- the **creation journal** the CLI appends to after a successful write,
  `<workspace>/.tours/.log/creations/<createdAtMs>-<pid>-<rand>.json`, whose
  record carries the workspace, the absolute Tour path, the title, the kind, the
  creation time and the session identity of the creating process;
- the **session transcript** the Copilot CLI names in the hook payload
  (`transcriptPath`, the session's `events.jsonl`), for the response boundary
  and the token figures.

A Tour is reported only when its attribution is established: the payload
`sessionId` matches the record's session identity (a record without one, or
with another agent's host, is never attributed), the canonical workspace is the
payload `cwd`, and the record was created inside the current response —
between the last `user.message` and the stop. All attributed Tours are printed
with their absolute path, oldest first.

One token reading follows, for the response as a whole and never per Tour:

```text
CodeTour: 2 Tours created in this response
CodeTour: "Flux de facturation" — /workspace/.tours/billing.tour
CodeTour: "Revue critique des changements" — /workspace/.tours/review.tour
CodeTour: tokens 38,608 in (of which 18,818 cached reads, 19,784 cached writes), 23 out
```

- `inputTokens` already contains the cache reads and writes, so cache is shown
  as a part of the input total and is never added to it; `reasoningTokens` is a
  subset of the output.
- Figures the session never recorded are omitted; a window with no usage record
  says `tokens unavailable (…)`, never zero.
- A fallback boundary (no `user.message` in the transcript, the resumed-session
  case) labels the whole reading `(approximate)`.
- One reading per response: the hook writes
  `<workspace>/.tours/.log/creations/.reported/<sessionId>-<responseStartMs>`
  and stays silent on a second stop of the same response.

No creation identified means no output at all. The hook always exits 0 and
always answers `{}`: it never blocks, never asks for a continuation and never
calls a model. It cannot fail a creation — a journal it cannot read is a
diagnostic, and an unavailable token figure only shortens the summary.

## Requirements

- GitHub Copilot CLI 1.0.106 or later (verified with 1.0.114). The plugin relies
  on `${PLUGIN_ROOT}` expansion and on the `agentStop` hook payload
  (`sessionId`, `timestamp`, `cwd`, `transcriptPath`, `stopReason`,
  `stop_hook_active`).
- `codetour` on `PATH`: the skill runs the installed CLI from the workspace
  root, and no launcher is recorded in the plugin.
- Node on `PATH` for the hook command (`node "${PLUGIN_ROOT}/…"`).
- Session usage records in the transcript: without them the summary reports the
  tokens as unavailable.

### Verified limits

- The hook writes to stderr, as the previous hook did. On Copilot CLI 1.0.114
  stderr is not shown in prompt mode (`-p`) and the only honoured `agentStop`
  output is `{}` or a block decision, which would cost a model turn; the
  interactive TUI could not be exercised during recon. The summary is therefore
  produced on every stop but is not proven visible in every mode.
- `agentStop` is not guaranteed once per response (a `task_complete` stop adds
  one); the response marker is what keeps the reading single.
- The session events format is Copilot-internal, so every figure degrades to
  "unavailable" instead of failing the stop.
- macOS and Linux path handling uses Node APIs and has been exercised with
  spaces in the installed plugin path and the workspace path. Windows was not
  executed in this environment; the hook uses `exec`-free Node APIs and the
  declaration quotes `${PLUGIN_ROOT}`, but Windows remains unverified.
